/**
 * Generate Mutation Payload to Update DataPoint Frequencies
 * 
 * INPUT:
 *   $ (payload): Query response with DataPoint edges
 *   {
 *     dataPoint: {
 *       total: 8153,
 *       edges: [{ node: { id, code, frequency } }, ...]
 *     }
 *   }
 * 
 * OUTPUT:
 *   [{ where: { id }, update: { frequency } }, ...]
 * 
 * FREQUENCY DISTRIBUTION (Option C - Reduced Volume):
 *   Range: 5 seconds (5000ms) to 60 seconds (60000ms)
 *   Target Average: ~41 seconds
 *   Target Records/Hour: ~988K
 */

'use strict';

// Extract DataPoints from query response
var edges = ($ && $.dataPoint && $.dataPoint.edges) || [];

// Frequency buckets (milliseconds) with weights
// Weighted heavily toward slower frequencies to reduce data volume
var frequencyBuckets = [
  { freq: 5000,  weight: 0.02 },  // 5s  -  2% (critical sensors only)
  { freq: 10000, weight: 0.02 },  // 10s -  3% (high-priority sensors)
  { freq: 15000, weight: 0.09 },  // 15s - 10%
  { freq: 30000, weight: 0.25 },  // 30s - 25%
  { freq: 45000, weight: 0.30 },  // 45s - 30%
  { freq: 60000, weight: 0.32 }   // 60s - 30%
];

// Calculate cumulative weights for weighted random selection
var cumulativeWeights = [];
var cumulative = 0;
for (var i = 0; i < frequencyBuckets.length; i++) {
  cumulative += frequencyBuckets[i].weight;
  cumulativeWeights.push(cumulative);
}

// Weighted random frequency selection
function selectFrequency() {
  var rand = Math.random();
  for (var i = 0; i < cumulativeWeights.length; i++) {
    if (rand <= cumulativeWeights[i]) {
      return frequencyBuckets[i].freq;
    }
  }
  return frequencyBuckets[frequencyBuckets.length - 1].freq;
}

// Generate update payload
var payload = [];
var frequencyStats = {};

for (var i = 0; i < edges.length; i++) {
  var dp = edges[i].node;
  var newFrequency = selectFrequency();
  
  payload.push({
    where: { id: dp.id },
    update: { frequency: newFrequency }
  });
  
  // Track stats
  var freqKey = newFrequency.toString();
  if (!frequencyStats[freqKey]) {
    frequencyStats[freqKey] = 0;
  }
  frequencyStats[freqKey]++;
}

// Calculate and log statistics
var totalFreq = 0;
var totalRecordsPerHour = 0;
var frequencies = Object.keys(frequencyStats).sort(function(a, b) { 
  return parseInt(a) - parseInt(b); 
});

console.log('Frequency Distribution:');
for (var i = 0; i < frequencies.length; i++) {
  var freq = parseInt(frequencies[i]);
  var count = frequencyStats[freq];
  var samplesPerHour = 3600000 / freq;
  var recordsPerHour = count * samplesPerHour;
  
  totalFreq += freq * count;
  totalRecordsPerHour += recordsPerHour;
  
  console.log('  ' + (freq / 1000) + 's: ' + count + ' DataPoints (' + 
    Math.round(count / edges.length * 100) + '%) → ' + 
    Math.round(recordsPerHour).toLocaleString() + ' records/hr');
}

var avgFreq = totalFreq / edges.length;

console.log('');
console.log('Frequency Update Summary:');
console.log('  Total DataPoints: ' + edges.length);
console.log('  Average Frequency: ' + (avgFreq / 1000).toFixed(1) + ' seconds');
console.log('  Range: 5s - 60s');
console.log('');
console.log('Projected Data Volume:');
console.log('  Records/Hour: ' + Math.round(totalRecordsPerHour).toLocaleString());
console.log('  Records/Day: ' + Math.round(totalRecordsPerHour * 24).toLocaleString());
console.log('  Records/5min Window: ' + Math.round(totalRecordsPerHour / 12).toLocaleString());

return payload;

data.query:
query DataPoint($where: DataPointWhereInput, $orderBy: [DataPointOrderByInput!], $first: Int, $after: String) {
  dataPoint(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    total
    edges {
      node {
        id
        code
        frequency
      }
    }
  }
}

